    "tableId": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "ID tej tabeli:" } },
    "description": { "t": 0, "b": { "t": 2, "i": [{ "t": 3, "v": "Każdy wiersz w tabeli " }, { "t": 4, "k": "name" }, { "t": 3, "v": " zawiera następujące pola." }] } },
    "id": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "ID" } },
    "name": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Nazwa" } },
