    "projectsNotesRow1": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Acme zamierza całkowicie zmienić wizerunek swojej strony internetowej zgodnie z następującymi wytycznymi." } },
    "projectsNotesRow2": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Sprawdź, czy obecni użytkownicy Soylent są zainteresowani nowym portalem użytkownika." } },
    "projectsNotesRow3": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Zastanawiamy się, czy warto to zrobić po bojkocie reklam na Facebooku. Badania pokazują, że płatne kampanie reklamowe stają się coraz mniej efektywne." } },
    "teamsRoleDesigner": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Projektant" } },
