    "teamsRoleMarketer": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Specjalista od Marketingu" } },
    "tasksDetailsRow1": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Logo wymaga poprawy, aby wyraźniej wyeksponować wezwanie do działania (CTA)." } },
    "tasksDetailsRow2": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Struktura nie jest taka, jaka powinna być, więc może trzeba będzie również poprawić mapę witryny." } },
    "tasksDetailsRow3": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Nowa stopka powinna zawierać nasze dane kontaktowe, jak również dyskretne (ale zdecydowane) wezwanie do działania (CTA)." } },
    "campaignsDetailsRow1": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Zaoszczędź dzięki naszej letniej promocji i niepowtarzalnym rabatom na wszystkie Twoje ulubione produkty!" } },
    "campaignsDetailsRow2": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Zahamuj odpływ klientów i zwiększ ich zaangażowanie dzięki naszemu atrakcyjnemu programowi lojalnościowemu, stworzonemu z myślą o tym, by nagradzać Twoich najlepszych klientów." } },
    "campaignsDetailsRow3": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Ożyw swoją działalność i przyciągnij uwagę odbiorców dzięki dynamicznemu rebrandingowi marki. Idealnie wpisze się w dzisiejsze trendy rynkowe i oczekiwania klientów." } },
